let palette;
function preload(){
  Shader=getShader(this._renderer);
	palette = loadImage("data:image/png;base64,iVBORw0KGgoAAAANSUhEUgAAAQAAAAABCAYAAAAxWXB3AAAAAXNSR0IArs4c6QAAAGRJREFUOE9jZGBg+M8ABiwMDAwcSDQyGyZHSIyQPDZzOJCsZoE6AUaDnIRDDGwUmjqYGNwrUHmQOnQxFoQc3FVIykE+AWNai7EwMPxhQOAfFLBB5gyE/uHlAeTYGM5sUEphYAAAjJafAWvSA74AAAAASUVORK5CYII=");
}
function setup() {
	pixelDensity(1);
  createCanvas(windowWidth,windowHeight,WEBGL);
  noStroke();
}
function draw() {
  shader(Shader);
	Shader.setUniform('pal', palette);
	Shader.setUniform('c', [cos(frameCount/256+PI/2)*0.8,sin(frameCount/256+PI/2)*0.8]);
  rect(0,0,width,height);
}
function mousePressed() {
	save("Frozen_Fractal");
}
function getShader(_renderer) {
	const vert=`
		precision highp float;
		attribute vec3 aPosition;
		attribute vec2 aTexCoord;
		varying vec2 vTexCoord;
		void main() {
			vTexCoord=aTexCoord;
			vec4 positionVec4=vec4(aPosition,1.);
			positionVec4.xy=positionVec4.xy*2.-1.; 
			gl_Position=positionVec4;
		}
	`;
	const frag=`
		precision highp float;
		varying vec2 vTexCoord;
		uniform sampler2D pal;
		uniform vec2 c;
		const float zh=${windowHeight/windowWidth};
		void main() {
			vec2 z=vec2(5.*vTexCoord.x-2.5,(5.*vTexCoord.y-2.5)*zh);
			int iter=100;
			for(int i=0;i<100;i++) {
				float x=(z.x+z.y)*(z.x-z.y)+c.x;
				float y=2.*z.y*z.x+c.y;
				if((x*x+y*y)>4.) {iter=i;break;}
				z.x=x;
				z.y=y;
			}
			gl_FragColor = texture2D(pal,vec2(iter==100?0.0:float(iter)/100.0,1));
		}
	`;
	return createShader(vert, frag);
}

